static uintptr_t align8(uintptr_t p){return (p+7u)&~(uintptr_t)7u;}
rsm_status_t rsm_runtime_init(rsm_runtime_t*r,void*a,size_t z,const rsm_hal_t*h,void*c){if(!r||!a||!h||!h->monotonic_time_us)return RSM_STATUS_INVALID_ARGUMENT;memset(r,0,sizeof *r);r->arena=a;r->arena_size=z;r->hal=*h;r->hal_context=c;r->mode=RSM_MODE_PROGRAM;return RSM_STATUS_OK;}
