static void prescan(impl_t*m){uint32_t i;for(i=0;i<m->states;i++){m->state[i].edge=1;m->state[i].valid=0;}for(i=0;i<m->tags;i++){if(m->tag[i].type==4){m->tag[i].v.timer.en=m->tag[i].v.timer.tt=m->tag[i].v.timer.dn=0;}else if(m->tag[i].type==5){m->tag[i].v.counter.cu=m->tag[i].v.counter.cd=0;}}}
rsm_status_t rsm_runtime_set_mode(rsm_runtime_t*r,rsm_mode_t mode){if(!r||mode>RSM_MODE_FAULTED)return RSM_STATUS_INVALID_ARGUMENT;if((mode==RSM_MODE_RUN||mode==RSM_MODE_TEST)&&!r->impl)return RSM_STATUS_INVALID_STATE;if(r->mode==RSM_MODE_FAULTED&&mode!=RSM_MODE_PROGRAM)return RSM_STATUS_INVALID_STATE;if((mode==RSM_MODE_RUN||mode==RSM_MODE_TEST)&&(r->mode==RSM_MODE_PROGRAM)){prescan(r->impl);}if(mode==RSM_MODE_PROGRAM&&r->impl)prescan(r->impl);r->mode=mode;return RSM_STATUS_OK;}
rsm_mode_t rsm_runtime_get_mode(const rsm_runtime_t*r){return r?r->mode:RSM_MODE_FAULTED;}
rsm_status_t rsm_runtime_scan(rsm_runtime_t*r){impl_t*m;size_t o=0;uint32_t index=0,rung=0;bool power=true;uint64_t start,end;if(!r||!r->impl)return RSM_STATUS_INVALID_ARGUMENT;if(r->mode!=RSM_MODE_RUN&&r->mode!=RSM_MODE_TEST)return r->mode==RSM_MODE_FAULTED?RSM_STATUS_FAULTED:RSM_STATUS_INVALID_STATE;m=r->impl;start=now(r);m->diag.last_scan_start_us=start;
/* Inputs are captured once. Endpoint IDs intentionally equal dense tag IDs. */
{uint32_t i;for(i=0;i<m->tags;i++)if(m->tag[i].storage==1&&r->hal.read_input){rsm_value_t v;rsm_status_t s;value(m,i,&v);s=r->hal.read_input(r->hal_context,i,&v);if(s)return fail(r,RSM_FAULT_HAL,1,"INPUT",NONE,0,i);if(v.type!=(rsm_data_type_t)m->tag[i].type)return fail(r,RSM_FAULT_HAL,2,"INPUT_TYPE",NONE,0,i);if(v.type==RSM_TYPE_BOOL)m->tag[i].v.b=v.value.boolean?1u:0u;else if(v.type==RSM_TYPE_DINT)m->tag[i].v.d=v.value.dint;else m->tag[i].v.f=v.value.real;}}
while(o<m->code_size){uint8_t ac;if(rung<m->rungs&&index==u32(m->rung_data+(size_t)rung*12u+4)){power=true;rung++;}ac=m->code[o+1];if(execute(r,m->code+o,&power,start))return RSM_STATUS_FAULTED;o+=12u+(size_t)ac*8u;index++;}
if(r->mode==RSM_MODE_RUN&&r->hal.write_output){uint32_t i;for(i=0;i<m->tags;i++)if(m->tag[i].storage==2){rsm_value_t v;if(value(m,i,&v)||r->hal.write_output(r->hal_context,i,&v))return fail(r,RSM_FAULT_HAL,3,"OUTPUT",NONE,0,i);}}
end=now(r);m->diag.last_scan_duration_us=end-start;m->diag.scan_count++;if(m->diag.last_scan_duration_us>m->diag.max_scan_duration_us)m->diag.max_scan_duration_us=m->diag.last_scan_duration_us;m->diag.average_scan_duration_us+=(m->diag.last_scan_duration_us-m->diag.average_scan_duration_us)/m->diag.scan_count;if(r->hal.kick_watchdog&&r->hal.kick_watchdog(r->hal_context))return fail(r,RSM_FAULT_WATCHDOG,1,"WATCHDOG",NONE,0,NONE);return RSM_STATUS_OK;}
rsm_status_t rsm_runtime_snapshot(const rsm_runtime_t*r,rsm_snapshot_writer_t*w){impl_t*m;uint32_t i;if(!r||!r->impl||!w||!w->value)return RSM_STATUS_INVALID_ARGUMENT;m=r->impl;for(i=0;i<m->tags;i++)if(m->tag[i].type<=3){rsm_value_t logical,effective;logical.type=(rsm_data_type_t)m->tag[i].type;if(logical.type==RSM_TYPE_BOOL)logical.value.boolean=m->tag[i].v.b;else if(logical.type==RSM_TYPE_DINT)logical.value.dint=m->tag[i].v.d;else logical.value.real=m->tag[i].v.f;effective=logical;if(m->force[i].enabled)effective=m->force[i].value;{rsm_status_t s=w->value(w->context,i,&logical,&effective,m->force[i].enabled);if(s)return s;}}return RSM_STATUS_OK;}
rsm_status_t rsm_runtime_get_diagnostics(const rsm_runtime_t*r,rsm_runtime_diagnostics_t*d){if(!r||!r->impl||!d)return RSM_STATUS_INVALID_ARGUMENT;*d=((impl_t*)r->impl)->diag;return RSM_STATUS_OK;}
const rsm_fault_t *rsm_runtime_last_fault(const rsm_runtime_t*r){return (r&&r->impl)?&((impl_t*)r->impl)->fault:NULL;}
